//! 📨️ A deferred response captures the actual cached view and admitted actor once under its original continuation.
use super::*;
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::RetainedCloneClose};
use semio_framework_plugin_plugin_program::surface_context::OriginalSurfaceViewCapture;
use std::mem::{ManuallyDrop,size_of};
/// 🧷️ Every retry borrows this same source; cancellation restores the cache before its caller returns.
pub struct OriginalResponseActionSource{instance:u32,binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,surface:Option<(usize,usize)>,capture:ManuallyDrop<Option<Box<OriginalSurfaceViewCapture>>>,view:ManuallyDrop<Option<semio_framework::ViewModel>>,actor:ManuallyDrop<Option<String>>,pub metadata:ManuallyDrop<Option<ActionMeta>>,actor_source:Option<(usize,usize)>,offset:usize,phase:u8,retirement:RetainedCloneClose}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"response metadata changed its actual instance, actor, caller or receiving recipient")}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl OriginalResponseActionSource{
 fn admit_selection(instance:u32,surface:Option<&str>,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..header::<Self>()};let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;admit_original_construction(cx,output,construction(d),|native|{let decoder=(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::new(Self{instance,binding,decoder,body,surface:surface.map(|surface|(surface.as_ptr()as usize,surface.len())),capture:ManuallyDrop::new(None),view:ManuallyDrop::new(None),actor:ManuallyDrop::new(None),metadata:ManuallyDrop::new(None),actor_source:None,offset:0,phase:0,retirement:Default::default()}),progress(d)))})}
 pub fn admit(instance:u32,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{Self::admit_selection(instance,None,cx,output)}
 /// 🎯️ The selected original surface text remains borrowed from its retained intent throughout capture and handback.
 pub fn admit_surface(instance:u32,surface:&str,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{Self::admit_selection(instance,Some(surface),cx,output)}
 fn validate_surface(&self,surface:Option<&str>)->Result<(),OriginalTurnFailure>{if self.surface!=surface.map(|surface|(surface.as_ptr()as usize,surface.len())){return Err(invalid().into())}Ok(())}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn advance_cache(&mut self,surface:Option<&str>,registry:&mut semio_framework_plugin_plugin_program::surface_context::SurfaceContexts,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.validate_surface(surface)?;match self.phase{0=>{if self.capture.is_none(){OriginalSurfaceViewCapture::admit(cx,&mut self.capture)?;return Ok(false)}if match surface{Some(surface)=>self.capture.as_mut().unwrap().advance_surface(registry,surface,cx)?,None=>self.capture.as_mut().unwrap().advance(registry,cx)?}{self.phase=1}},1=>{if self.capture.as_mut().unwrap().take_into(&mut self.view,cx)?{self.phase=2}},_=>{}}Ok(self.phase>=2)}
 fn advance_actor(&mut self,text:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;match self.phase{
  2=>{let d=RetirementDemand{capacity_bytes:text.len(),..header::<String>()};let source=(text.as_ptr()as usize,text.len());let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{*self.actor=Some(String::with_capacity(text.len()));self.actor_source=Some(source);self.phase=3;Ok(((),progress(d)))})?;},
  3=>{if self.actor_source!=Some((text.as_ptr()as usize,text.len())){return Err(invalid().into())}let mut end=(self.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1}let d=RetirementDemand{copy_bytes:end-self.offset+size_of::<usize>()+size_of::<u8>(),depth:1,..Default::default()};let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{self.actor.as_mut().unwrap().push_str(&text[self.offset..end]);self.offset=end;if end==text.len(){self.phase=4}Ok(((),progress(d)))})?;},
  4=>{let mut d=semio_framework_value::SharedUtf8::admission_demand();d.copy_bytes=2*size_of::<ActionMeta>()+size_of::<String>();let g=cx.retained_grant();if admit_original_construction(cx,&mut self.metadata,construction(d),|_|{let(actor,_)=semio_framework_value::SharedUtf8::admit(self.actor.take().unwrap(),g).unwrap_or_else(|_|unreachable!("funded original actor header"));Ok((ActionMeta{actor,instance_id:self.instance,view_state:self.view.take()},progress(d)))})?{self.phase=5}},5=>return Ok(true),_=>return Err(invalid().into())}Ok(self.phase==5)}
 async fn advance_selected<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,surface:Option<&str>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.validate_surface(surface)?;if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"response metadata capture cancelled").into())}if self.phase<2{return with_instances_turn_mut(runtime,|list|{let mut instance=find_instance(list,self.instance)?;self.advance_cache(surface,&mut instance.surface_contexts,cx).map(|_|false)}).await}let actors=runtime.instance_actors.try_borrow().map_err(|_|invalid())?;let actor=actors.get(self.instance).ok_or_else(invalid)?;let text=std::str::from_utf8(&actor.bytes[..usize::from(actor.len)]).map_err(|_|invalid())?;self.advance_actor(text,cx)}
 pub fn ready(&self)->bool{self.phase==5}
 pub async fn advance<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.advance_selected(runtime,None,cx).await}
 pub async fn advance_surface<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,surface:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.advance_selected(runtime,Some(surface),cx).await}
 pub async fn close_step<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if let Some(capture)=self.capture.as_mut(){if !capture.terminal_is_empty(){with_instances_turn_mut(runtime,|list|{let mut instance=find_instance(list,self.instance)?;capture.close_step(&mut instance.surface_contexts,cx)}).await?;return Ok(false)}let d=OriginalSurfaceViewCapture::release_demand();close_original_retained_step(cx,d,|_|{self.capture.take();Ok(RetainedCloneStep::Progress(progress(d)))})?;return Ok(false)}self.close_owned(cx)}
 /// 📏️ The selected original registry and retained body determine the next physical close action.
 pub fn close_demands(&self,registry:&semio_framework_plugin_plugin_program::surface_context::SurfaceContexts)->Result<RetirementDemand,ValueError>{if let Some(capture)=self.capture.as_ref(){return if capture.terminal_is_empty(){Ok(OriginalSurfaceViewCapture::release_demand())}else{capture.close_demands(registry)}}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.metadata.is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,self.body)}if self.view.is_some(){return self.retirement.next_owner_demands::<semio_framework::ViewModel>(true,&None,self.body)}if self.actor.is_some(){return self.retirement.next_owner_demands::<String>(true,&None,self.body)}Ok(Default::default())}
 fn close_owned(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.retirement.is_empty(){let selected=self.retirement.select(self.body)?;let d=selected.demands();close_original_retained_step(cx,d,|g|selected.step(g))?;return Ok(false)}macro_rules! close{($field:ident,$ty:ty)=>{if self.$field.is_some(){let d=self.retirement.next_owner_demands::<$ty>(true,&None,self.body)?;close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.$field,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;return Ok(false)}}}close!(metadata,ActionMeta);close!(view,semio_framework::ViewModel);close!(actor,String);Ok(true)}
 pub fn terminal_is_empty(&self)->bool{self.capture.is_none()&&self.view.is_none()&&self.actor.is_none()&&self.metadata.is_none()&&self.retirement.is_empty()}
 pub fn release_demand()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalResponseActionSource{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"response metadata source requires original physical closure")}}

